WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, k, value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) x AS k, value) SELECT customer_id, COUNT(*) AS row_count, SIZE(COLLECT_SET(k)) AS num_ks, COUNT_IF(k = 'weight_kg') AS weight_kg_events, COUNT(DISTINCT k) AS distinct_ks, COUNT(*) FILTER (WHERE k = 'weight_kg') AS weight_kg_rows, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM flattened GROUP BY customer_id ORDER BY duration_min
